"""Minimal fake psycopg connection so the real psycopg_pool + Django wrapper
code paths can be exercised without a PostgreSQL server."""
import threading
from psycopg.pq import TransactionStatus

CONNECT_LOG = []


class FakePGConn:
    transaction_status = TransactionStatus.IDLE
    status = 0


class FakeInfo:
    server_version = 150000

    def __init__(self, dbname):
        self.dbname = dbname

    def parameter_status(self, name):
        return "UTC"


class FakeLoader:
    timezone = None


class FakeAdapters:
    def get_loader(self, *a):
        return FakeLoader()

    def register_loader(self, *a):
        pass


class FakeCursor:
    def __init__(self, conn):
        self.connection = conn
        self.adapters = FakeAdapters()

    def __enter__(self):
        return self

    def __exit__(self, *a):
        pass

    def execute(self, sql, params=None):
        self.connection.executed.append((threading.current_thread().name, str(sql), params))

    def close(self):
        pass


class FakeConn:
    _pool = None
    closed = False
    broken = False

    def __init__(self, kwargs):
        self.kwargs = kwargs
        self.pgconn = FakePGConn()
        self.info = FakeInfo(kwargs.get("dbname"))
        self.adapters = FakeAdapters()
        self.autocommit = kwargs.get("autocommit", False)
        self.isolation_level = None
        self.executed = []

    @classmethod
    def connect(cls, conninfo="", **kwargs):
        CONNECT_LOG.append((threading.current_thread().name, kwargs.get("dbname")))
        return cls(kwargs)

    def cursor(self, *a, **kw):
        return FakeCursor(self)

    def commit(self):
        pass

    def rollback(self):
        pass

    def close(self):
        self.closed = True
EOF
cat > repro_testdb.py <<'EOF'
import sys, warnings
from unittest import mock
import django
from django.conf import settings
import fakepg

scenario = sys.argv[1]
settings.configure(
    DATABASES={
        "default": {
            "ENGINE": "django.db.backends.postgresql",
            "NAME": "proddb",
            "OPTIONS": {"pool": {"connection_class": fakepg.FakeConn, "min_size": 1, "max_size": 2, "timeout": 3}},
        }
    },
    INSTALLED_APPS=[],
)
django.setup()
from django.db import connection
from django.db.backends.postgresql.base import DatabaseWrapper
import psycopg

patches = [mock.patch("django.core.management.call_command")]
if scenario == "early-query":
    # A query issued before the test runner sets up databases (AppConfig.ready(),
    # module import, ...).
    with connection.cursor() as c:
        c.execute("SELECT 1")
    print("early query went to dbname =", connection.connection.info.dbname)
    # Pretend CREATE DATABASE via the 'postgres' db succeeded.
    patches.append(mock.patch.object(type(connection.creation), "_create_test_db"))
elif scenario == "nodb-fallback":
    # The maintenance 'postgres' database is not reachable -> documented fallback.
    def fake_connect(*a, **kw):
        raise psycopg.OperationalError("no access to database %s" % kw.get("dbname"))
    patches.append(mock.patch.object(DatabaseWrapper.Database, "connect", fake_connect))

with warnings.catch_warnings():
    warnings.simplefilter("ignore")
    for p in patches:
        p.start()
    name = connection.creation.create_test_db(verbosity=0, serialize=False)
    for p in patches:
        p.stop()

print("create_test_db returned:", name)
print("settings_dict NAME     :", connection.settings_dict["NAME"])
with connection.cursor() as c:
    c.execute("TRUNCATE important_table")
print("test-time query ran on :", connection.connection.info.dbname)
print("pool kwargs dbname     :", connection.pool.kwargs["dbname"])
print("connect log            :", fakepg.CONNECT_LOG)
connection.close(); connection.close_pool()
EOF
